def chunk(text, size=4, overlap=1):
    words = text.split()
    step = size - overlap
    return [" ".join(words[i:i + size]) for i in range(0, max(len(words) - overlap, 1), step)]
for c in chunk("a b c d e f g h i j"):
    print(c)

import math
from collections import Counter
def embed(t): return Counter(t.lower().split())
def cos(a, b):
    dot = sum(a[k] * b[k] for k in a if k in b)
    return dot / (math.sqrt(sum(v*v for v in a.values())) * math.sqrt(sum(v*v for v in b.values())))
docs = ["refund within 30 days", "express shipping 2 days", "refund method original payment"]
q = embed("how long for refund")
scores = [(round(cos(q, embed(d)), 3), d) for d in docs]
for s, d in sorted(scores, reverse=True):
    print(s, d)
